  ],
  "author": "",
  "license": "MIT"
}

const request = require('supertest');
const app = require('./app');

describe('POST /users validation tests', () => {
  test('should return 400 when name is missing', async () => {
    const response = await request(app)
      .post('/users')
      .send({});

    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Missing required field: name');
  });

  test('should return 400 when name is null', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: null });

    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Missing required field: name');
  });

  test('should return 400 when name is not a string', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 });

    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Field "name" must be a string');
  });

  test('should return 400 when name is empty string', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' });

    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Field "name" cannot be empty or whitespace only');
  });

  test('should return 400 when name is whitespace only', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '   ' });

    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Field "name" cannot be empty or whitespace only');
  });

  test('should return 201 when name is valid', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'John Doe' });

    expect(response.statusCode).toBe(201);
    expect(response.body.message).toBe('User created successfully');
    expect(response.body.name).toBe('John Doe');
    expect(response.body.id).toBeDefined();
  });

  test('should trim whitespace from valid name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '  Jane Smith  ' });

    expect(response.statusCode).toBe(201);
    expect(response.body.name).toBe('Jane Smith');
  });
});

describe('GET endpoints', () => {
  test('GET /health should return 200', async () => {
    const response = await request(app).get('/health');
    expect(response.statusCode).toBe(200);
    expect(response.body.status).toBe('ok');
  });

  test('GET /users should return user list', async () => {
    const response = await request(app).get('/users');
    expect(response.statusCode).toBe(200);
    expect(Array.isArray(response.body)).toBe(true);
    expect(response.body.length).toBe(2);
  });
});

