const express = require('express');
const app = express();

// Middleware to parse JSON request bodies
app.use(express.json());

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST handler with input validation
app.post('/users', (req, res) => {
  // Check if name field exists in request body
  if (req.body.name === undefined) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Missing required field: name'
    });
  }

  // Check if name is a string
  if (typeof req.body.name !== 'string') {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Field "name" must be a string'
    });
  }

  // Check if name is empty or only whitespace
  if (req.body.name.trim() === '') {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Field "name" cannot be empty or only whitespace'
    });
  }

  // If validation passes, process the request
  // For now, just return a success response with the validated name
  res.status(201).json({
    message: 'User created successfully',
    data: {
      id: Date.now(), // Generate a simple ID for demo purposes
      name: req.body.name.trim() // Return trimmed name
    }
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

