const request = require('supertest');
const app = require('../app.js');

describe('POST /users validation tests', () => {
  test('should return 201 for valid name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'John' })
      .set('Accept', 'application/json');

    expect(response.statusCode).toBe(201);
    expect(response.body.message).toBe('User created successfully');
    expect(response.body.user.name).toBe('John');
  });

  test('should return 400 for missing name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({})
      .set('Accept', 'application/json');

    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Validation failed');
    expect(response.body.message).toBe('The "name" field is required');
  });

  test('should return 400 for null name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: null })
      .set('Accept', 'application/json');

    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Validation failed');
    expect(response.body.message).toBe('The "name" field is required');
  });

  test('should return 400 for non-string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 })
      .set('Accept', 'application/json');

    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Validation failed');
    expect(response.body.message).toBe('The "name" field must be a string');
  });

  test('should return 400 for name as boolean', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: true })
      .set('Accept', 'application/json');

    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Validation failed');
    expect(response.body.message).toBe('The "name" field must be a string');
  });

  test('should return 400 for name as object', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: { first: 'John', last: 'Doe' } })
      .set('Accept', 'application/json');

    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Validation failed');
    expect(response.body.message).toBe('The "name" field must be a string');
  });
});

