#!/usr/bin/env node

// Simple test script for POST /users endpoint
const http = require('http');

const testCases = [
  {
    name: 'Valid request',
    method: 'POST',
    path: '/users',
    data: { name: 'John Doe' },
    expectedStatus: 201,
    description: 'Should accept valid name string'
  },
  {
    name: 'Missing name field',
    method: 'POST',
    path: '/users',
    data: { email: 'john@example.com' },
    expectedStatus: 400,
    description: 'Should reject missing name field'
  },
  {
    name: 'Non-string name',
    method: 'POST',
    path: '/users',
    data: { name: 123 },
    expectedStatus: 400,
    description: 'Should reject non-string name'
  },
  {
    name: 'Empty name',
    method: 'POST',
    path: '/users',
    data: { name: '' },
    expectedStatus: 400,
    description: 'Should reject empty name'
  },
  {
    name: 'Whitespace name',
    method: 'POST',
    path: '/users',
    data: { name: '   ' },
    expectedStatus: 400,
    description: 'Should reject whitespace-only name'
  }
];

function makeRequest(testCase, callback) {
  const postData = JSON.stringify(testCase.data);

  const options = {
    hostname: 'localhost',
    port: 3000,
    path: testCase.path,
    method: testCase.method,
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      try {
        const parsed = JSON.parse(data);
        callback(null, {
          statusCode: res.statusCode,
          body: parsed,
          testCase: testCase
        });
      } catch (e) {
        callback(e);
      }
    });
  });

  req.on('error', (e) => {
    callback(e);
  });

  req.write(postData);
  req.end();
}

function runTests() {
  console.log('Starting POST /users endpoint validation tests...\n');

  let passed = 0;
  let failed = 0;

  testCases.forEach((testCase, index) => {
    setTimeout(() => {
      makeRequest(testCase, (err, result) => {
        if (err) {
          console.log(`❌ ${testCase.name}: ERROR - ${err.message}`);
          failed++;
        } else if (result.statusCode === testCase.expectedStatus) {
          console.log(`✅ ${testCase.name}: PASSED (Status: ${result.statusCode})`);
          console.log(`   ${testCase.description}`);
          passed++;
        } else {
          console.log(`❌ ${testCase.name}: FAILED`);
          console.log(`   Expected: ${testCase.expectedStatus}, Got: ${result.statusCode}`);
          console.log(`   Response: ${JSON.stringify(result.body)}`);
          failed++;
        }

        // If this is the last test, show summary
        if (index === testCases.length - 1) {
          setTimeout(() => {
            console.log('\n' + '='.repeat(50));
            console.log(`TEST SUMMARY: ${passed} passed, ${failed} failed`);
            console.log('='.repeat(50));
            process.exit(failed > 0 ? 1 : 0);
          }, 500);
        }
      });
    }, index * 500); // Stagger requests
  });
}

// Check if server is running
const checkReq = http.request({
  hostname: 'localhost',
  port: 3000,
  path: '/health',
  method: 'GET'
}, (res) => {
  if (res.statusCode === 200) {
    console.log('Server is running. Starting tests...\n');
    runTests();
  } else {
    console.error(`Server health check failed: ${res.statusCode}`);
    process.exit(1);
  }
});

checkReq.on('error', (e) => {
  console.error(`Cannot connect to server on port 3000.`);
  console.error('Make sure the server is running with: node app.js');
  console.error(`Error: ${e.message}`);
  process.exit(1);
});

checkReq.end();

