#!/usr/bin/env node

const http = require('http');

const PORT = 3000;
const BASE_URL = `http://localhost:${PORT}`;

const testCases = [
  {
    name: 'Valid request',
    method: 'POST',
    path: '/users',
    data: { name: 'John Doe' },
    expectedStatus: 201,
    description: 'Should accept valid name string'
  },
  {
    name: 'Missing name field',
    method: 'POST',
    path: '/users',
    data: { age: 30 },
    expectedStatus: 400,
    description: 'Should reject missing name field'
  },
  {
    name: 'Name is null',
    method: 'POST',
    path: '/users',
    data: { name: null },
    expectedStatus: 400,
    description: 'Should reject null name'
  },
  {
    name: 'Name is number',
    method: 'POST',
    path: '/users',
    data: { name: 123 },
    expectedStatus: 400,
    description: 'Should reject non-string name'
  },
  {
    name: 'Empty name',
    method: 'POST',
    path: '/users',
    data: { name: '' },
    expectedStatus: 400,
    description: 'Should reject empty name'
  },
  {
    name: 'Whitespace name',
    method: 'POST',
    path: '/users',
    data: { name: '   ' },
    expectedStatus: 400,
    description: 'Should reject whitespace-only name'
  }
];

function makeRequest(testCase) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'localhost',
      port: PORT,
      path: testCase.path,
      method: testCase.method,
      headers: {
        'Content-Type': 'application/json'
      }
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          body: data ? JSON.parse(data) : null
        });
      });
    });

    req.on('error', reject);

    if (testCase.data) {
      req.write(JSON.stringify(testCase.data));
    }
    req.end();
  });
}

async function runTests() {
  console.log('Testing POST /users input validation...\n');

  let passed = 0;
  let failed = 0;

  for (const testCase of testCases) {
    try {
      const result = await makeRequest(testCase);
      const passedTest = result.statusCode === testCase.expectedStatus;

      if (passedTest) {
        console.log(`✅ ${testCase.name}: ${testCase.description}`);
        passed++;
      } else {
        console.log(`❌ ${testCase.name}: ${testCase.description}`);
        console.log(`   Expected status ${testCase.expectedStatus}, got ${result.statusCode}`);
        console.log(`   Response: ${JSON.stringify(result.body)}`);
        failed++;
      }
    } catch (error) {
      console.log(`❌ ${testCase.name}: ${testCase.description}`);
      console.log(`   Error: ${error.message}`);
      failed++;
    }
  }

  console.log(`\nResults: ${passed} passed, ${failed} failed`);
  process.exit(failed > 0 ? 1 : 0);
}

// Check if server is running
const checkHealth = () => {
  return new Promise((resolve) => {
    const req = http.request({
      hostname: 'localhost',
      port: PORT,
      path: '/health',
      method: 'GET'
    }, (res) => {
      resolve(res.statusCode === 200);
    });

    req.on('error', () => resolve(false));
    req.end();
  });
};

async function main() {
  const isServerRunning = await checkHealth();

  if (!isServerRunning) {
    console.error('Error: Server is not running on port 3000');
    console.error('Please start the server first: npm start');
    process.exit(1);
  }

  await runTests();
}

main();

