  }
];

function runTest(testCase, callback) {
  const data = JSON.stringify(testCase.body);

  const options = {
    hostname: 'localhost',
    port: 3000,
    path: testCase.path,
    method: testCase.method,
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': data.length
    }
  };

  const req = http.request(options, (res) => {
    let responseData = '';

    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      const result = JSON.parse(responseData || '{}');
      const passed = res.statusCode === testCase.expectedStatus && 
                    result.message === testCase.expectedMessage;

      console.log(`Test: ${testCase.name}`);
      console.log(`  Expected: ${testCase.expectedStatus} - ${testCase.expectedMessage}`);
      console.log(`  Got: ${res.statusCode} - ${result.message}`);
      console.log(`  Result: ${passed ? '✓ PASSED' : '✗ FAILED'}`);
      console.log();

      callback(passed);
    });
  });

  req.on('error', (error) => {
    console.log(`Test: ${testCase.name}`);
    console.log(`  Error: ${error.message}`);
    console.log(`  Result: ✗ FAILED (Connection error)`);
    console.log();
    callback(false);
  });

  req.write(data);
  req.end();
}

console.log('Starting validation tests...\n');

// Run tests sequentially
let testIndex = 0;
let passedTests = 0;
let totalTests = testCases.length;

function runNextTest() {
  if (testIndex >= totalTests) {
    console.log(`\nTest Summary:`);
    console.log(`  Passed: ${passedTests}/${totalTests}`);
    process.exit(passedTests === totalTests ? 0 : 1);
    return;
  }

  runTest(testCases[testIndex], (passed) => {
    if (passed) passedTests++;
    testIndex++;
    runNextTest();
  });
}

runNextTest();

